namespace sv_da05f15d374a4520be44b2a0607f245d.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Circuit-scoped service that holds theme state and notifies subscribers on change.
/// Because all InteractiveServer components on a page share the same circuit,
/// and the circuit survives enhanced navigations, this service is the single
/// source of truth for the current user's theme across all pages.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island placed in the static MainLayout.
   Shares the circuit-scoped ThemeService with all other interactive components. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc
@inject IJSRuntime JS

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetThemeIcon(ThemeSvc.Theme) @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // Push the current theme to the DOM so static content is also themed.
        await ApplyThemeToDom();
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDom();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDom()
    {
        try
        {
            await JS.InvokeVoidAsync("themeInterop.apply", ThemeSvc.Theme.ToString(), ThemeSvc.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    private static string GetThemeIcon(ThemeMode mode) => mode switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _                => "🎨"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var isActive = ThemeSvc.Theme == mode;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnAccentChanged" />
            <span style="color: @ThemeSvc.AccentColor; font-weight: bold;">
                @ThemeSvc.AccentColor
            </span>
        </div>

        <div class="alert alert-info mb-0">
            Changes apply instantly to all components, including the header indicator.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

// Applies theme to the DOM so that both static and interactive content is styled.
window.themeInterop = {
    apply: function (theme, accentColor) {
        const root = document.documentElement;
        root.setAttribute('data-theme', theme.toLowerCase());
        root.style.setProperty('--accent-color', accentColor);

        localStorage.setItem('theme', theme);
        localStorage.setItem('accentColor', accentColor);
    },

    // Called on page load (before Blazor connects) to prevent flash of wrong theme.
    restore: function () {
        const theme = localStorage.getItem('theme');
        const accent = localStorage.getItem('accentColor');
        if (theme) document.documentElement.setAttribute('data-theme', theme.toLowerCase());
        if (accent) document.documentElement.style.setProperty('--accent-color', accent);
    }
};

// Restore immediately on script load.
window.themeInterop.restore();

